// Regression check for the isolated static prototype. Install Playwright outside the repo.
// FORMA_PLAYWRIGHT_MODULE points to that external installation; FORMA_QA_OUTPUT stores PNG evidence outside the repo.
const fs=require('fs'),path=require('path');const{chromium}=require(process.env.FORMA_PLAYWRIGHT_MODULE || 'playwright');
(async()=>{const b=await chromium.launch({headless:true,channel:'chromium'});const phase=process.argv[2]||'before',root=path.join(process.env.FORMA_QA_OUTPUT || require('os').tmpdir() + '/forma-text-resize',phase);fs.mkdirSync(root,{recursive:true});const result=[];for(const width of[375,390,768,1440,1920]){for(const scale of[1,2]){const p=await b.newPage({viewport:{width,height:width<768?844:width===768?1024:1080},reducedMotion:'reduce',hasTouch:width<768,isMobile:width<768});let r={width,scale,errors:[],failed:[],httpErrors:[],focus:[],menu:null};p.on('pageerror',e=>r.errors.push(e.message));p.on('console',m=>{if(m.type()==='error')r.errors.push(m.text())});p.on('requestfailed',q=>r.failed.push({url:q.url(),error:q.failure()}));p.on('response',s=>{if(s.status()>=400)r.httpErrors.push({url:s.url(),status:s.status()})});let response=await p.goto(process.env.FORMA_PREVIEW_URL || 'http://127.0.0.1:8110/',{waitUntil:'networkidle'});if(response.status()!==200)throw Error('HTTP not 200');await p.evaluate(async()=>{await document.fonts.ready;for(let y=0;y<document.body.scrollHeight;y+=500){scrollTo(0,y);await new Promise(r=>setTimeout(r,40))}scrollTo(0,0)});await p.waitForTimeout(200);if(scale===2)await p.evaluate(()=>{const es=[...document.querySelectorAll('body *')].filter(e=>!['SCRIPT','STYLE','SVG','PATH'].includes(e.tagName));const sizes=es.map(e=>parseFloat(getComputedStyle(e).fontSize));es.forEach((e,i)=>e.style.setProperty('font-size',sizes[i]*2+'px','important'))});r.layout=await p.evaluate(()=>{let rect=e=>e.getBoundingClientRect().toJSON();return{client:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth,innerWidth,contact:rect(document.querySelector('#contacts h2')),em:rect(document.querySelector('#contacts h2 em')),header:rect(document.querySelector('.header-inner')),h1:rect(document.querySelector('h1')),overflow:[...document.querySelectorAll('body *')].filter(e=>{let b=e.getBoundingClientRect();return b.width>0&&(b.right>document.documentElement.clientWidth+1||b.left< -1)}).slice(0,20).map(e=>({tag:e.tagName,cls:e.className,text:e.textContent.slice(0,70),box:rect(e)}))}});await p.screenshot({path:path.join(root,`${width}-${scale}x-viewport.png`)});await p.screenshot({path:path.join(root,`${width}-${scale}x-full.png`),fullPage:true});await p.locator('#contacts').scrollIntoViewIfNeeded();await p.screenshot({path:path.join(root,`${width}-${scale}x-contact.png`)});await p.evaluate(()=>scrollTo(0,0));
// Keyboard focus enters through skip-link, then header controls. Test reverse tab too.
await p.locator('body').click({position:{x:1,y:1}});for(let i=0;i<10;i++){await p.keyboard.press('Tab');r.focus.push(await p.evaluate(()=>{const e=document.activeElement,c=getComputedStyle(e);return{tag:e.tagName,cls:e.className,label:e.getAttribute('aria-label')||e.textContent.slice(0,70),box:e.getBoundingClientRect().toJSON(),outline:c.outlineStyle,outlineWidth:c.outlineWidth,outlineColor:c.outlineColor,focusVisible:e.matches(':focus-visible')}}))}await p.keyboard.press('Shift+Tab');r.reverseFocus=await p.evaluate(()=>document.activeElement.className);
const menu=p.getByRole('button',{name:/открыть меню|закрыть меню/i});if(await menu.isVisible()){await menu.focus();r.menu={closedBox:await menu.boundingBox()};await p.keyboard.press('Enter');r.menu.afterEnter=await menu.getAttribute('aria-expanded');r.menu.openBox=await menu.boundingBox();await p.screenshot({path:path.join(root,`${width}-${scale}x-menu.png`)});await p.keyboard.press('Escape');r.menu.afterEscape=await menu.getAttribute('aria-expanded');r.menu.focusAfterEscape=await menu.evaluate(e=>document.activeElement===e);await p.keyboard.press('Space');r.menu.afterSpace=await menu.getAttribute('aria-expanded');const link=p.locator('#mobile-navigation a[href="#contacts"]');await link.focus();await p.keyboard.press('Enter');await p.waitForTimeout(100);r.menu.afterLink=await menu.getAttribute('aria-expanded');r.menu.hash=new URL(p.url()).hash;}if(phase==='after'){const assert=require('assert/strict');assert.equal(r.layout.scroll,width);assert.equal(r.errors.length+r.failed.length+r.httpErrors.length,0);assert.ok(r.focus.every(f=>f.focusVisible&&f.outline==='solid'&&parseFloat(f.outlineWidth)>=2));if(r.menu){for(const box of[r.menu.closedBox,r.menu.openBox])assert.ok(box.x>=0&&box.x+box.width<=width&&box.y>=0&&box.height>=44);assert.equal(r.menu.afterEnter,'true');assert.equal(r.menu.afterSpace,'true');assert.equal(r.menu.afterEscape,'false');assert.equal(r.menu.afterLink,'false');assert.equal(r.menu.hash,'#contacts');assert.equal(r.menu.focusAfterEscape,true)}}result.push(r);fs.writeFileSync(path.join(root,'results.json'),JSON.stringify(result,null,2));console.log(JSON.stringify({phase,width,scale,scroll:r.layout.scroll,menu:r.menu,errors:r.errors.length,failed:r.failed.length}));await p.close()}}await b.close()})();
